initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentProducts = [];
  let selectedProductId = '';

  // テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!currentStoreId) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted);">該当する商品が見つかりません</td></tr>';
      noDataMessage.classList.add('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');
    tbody.innerHTML = products.map(product => {
      const prediction = getPredictionForProduct(product.商品ID);
      const currentStock = Math.floor(Math.random() * 100) + 10; // サンプル在庫数
      const predictedDemand = prediction ? prediction.予測数量 : Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - currentStock + 10);

      const stockStatus = currentStock < 20 ? 'status-low' : currentStock > 50 ? 'status-high' : 'status-normal';

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td><span class="status-badge ${stockStatus}">${currentStock}</span></td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>
            <div class="quantity-controls">
              <button class="quantity-btn minus-btn" data-id="${product.商品ID}">-</button>
              <input type="number" class="quantity-input" data-id="${product.商品ID}" value="${recommendedOrder}" min="0">
              <button class="quantity-btn plus-btn" data-id="${product.商品ID}">+</button>
            </div>
          </td>
          <td>
            <input type="text" class="reason-input" data-id="${product.商品ID}" placeholder="発注理由">
          </td>
          <td>
            <button class="action-btn secondary order-btn" data-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 需要予測結果表示
  function renderPredictionResults(storeId) {
    const predictionArea = container.querySelector('#prediction-results');
    if (!storeId) {
      predictionArea.innerHTML = '<p class="muted">店舗を選択すると需要予測結果が表示されます</p>';
      return;
    }

    const predictions = tables[8]?.records?.filter(p => p.店舗ID === storeId) || [];
    if (predictions.length === 0) {
      predictionArea.innerHTML = '<p class="muted">選択した店舗の需要予測データがありません</p>';
      return;
    }

    const totalPrediction = predictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const avgAccuracy = predictions.reduce((sum, p) => sum + (p.予測精度 || 0), 0) / predictions.length;

    predictionArea.innerHTML = `
      <div style="display: flex; gap: 24px;">
        <div>
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPrediction}</div>
          <div style="color: var(--text-muted); font-size: 14px;">総予測需要量</div>
        </div>
        <div>
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${Math.round(avgAccuracy)}%</div>
          <div style="color: var(--text-muted); font-size: 14px;">平均予測精度</div>
        </div>
        <div>
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${predictions.length}</div>
          <div style="color: var(--text-muted); font-size: 14px;">予測対象商品数</div>
        </div>
      </div>
    `;
  }

  // ヘルパー関数
  function getPredictionForProduct(productId) {
    return tables[8]?.records?.find(p => p.商品ID === productId && p.店舗ID === currentStoreId);
  }

  function getCategoryName(categoryId) {
    // サンプルカテゴリマッピング
    const categories = {
      'cat1': '食品',
      'cat2': '日用品', 
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || 'その他';
  }

  // 店舗選択肢の初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables[1]?.records || [];

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
  }

  // 仕入先選択肢の初期化
  function initSupplierOptions() {
    const supplierSelect = container.querySelector('#modal-supplier');
    // サンプル仕入先データ
    const suppliers = [
      { id: 'sup1', name: '株式会社サプライヤーA' },
      { id: 'sup2', name: '株式会社サプライヤーB' },
      { id: 'sup3', name: '株式会社サプライヤーC' }
    ];

    supplierSelect.innerHTML = '<option value="">仕入先を選択</option>' +
      suppliers.map(sup => `<option value="${sup.id}">${sup.name}</option>`).join('');
  }

  // フィルタリング関数
  function filterProducts() {
    const categoryFilter = container.querySelector('#category-select').value;
    const productSearch = container.querySelector('#product-search').value.toLowerCase();
    const dateStart = container.querySelector('#date-start').value;
    const dateEnd = container.querySelector('#date-end').value;

    let filtered = currentProducts;

    if (categoryFilter) {
      filtered = filtered.filter(p => getCategoryName(p.商品カテゴリID) === categoryFilter);
    }

    if (productSearch) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(productSearch) ||
        (p.商品コード || '').toLowerCase().includes(productSearch)
      );
    }

    renderProducts(filtered);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    if (startDate && endDate && startDate > endDate) {
      alert('終了日は開始日以降の日付を入力してください');
      return false;
    }
    return true;
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentProducts.length) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', 'カテゴリ', '現在在庫数', '予測需要量', '推奨発注量'];
    const rows = currentProducts.map(product => {
      const prediction = getPredictionForProduct(product.商品ID);
      const currentStock = Math.floor(Math.random() * 100) + 10;
      const predictedDemand = prediction ? prediction.予測数量 : Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - currentStock + 10);

      return [
        product.商品コード || '',
        product.商品名|| '',
        getCategoryName(product.商品カテゴリID),
        currentStock,
        predictedDemand,
        recommendedOrder
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 発注処理
  async function executeOrder(productId, quantity, reason) {
    const product = currentProducts.find(p => p.商品ID === productId);
    if (!product) return;

    const supplier = container.querySelector('#modal-supplier').value;
    const deliveryDate = container.querySelector('#modal-delivery-date').value;

    if (!supplier) {
      alert('仕入先を選択してください');
      return;
    }

    if (!deliveryDate) {
      alert('納期予定日を入力してください');
      return;
    }

    const orderData = {
      店舗ID: currentStoreId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(deliveryDate).toISOString(),
      発注数量: parseInt(quantity),
      発注単価: product.単価 || 100,
      発注金額: parseInt(quantity) * (product.単価 || 100),
      発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: supplier,
      発注理由: reason || 'AI推奨による発注',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(9, orderData);
    if (saved) {
      alert('発注が完了しました');
      container.querySelector('#order-modal').classList.add('hidden');
      // 発注済みフラグを更新
      const predictionIndex = tables[8]?.records?.findIndex(p => p.商品ID === productId && p.店舗ID === currentStoreId);
      if (predictionIndex >= 0) {
        await window.aivicApi.update(8, tables[8].records[predictionIndex].予測結果ID, { 発注済フラグ: true });
      }
    }
  }

  // 初期化
  initStoreOptions();
  initSupplierOptions();
  renderProducts([]);
  renderPredictionResults('');

  // イベントリスナー

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    currentStoreId = e.target.value;
    if (currentStoreId) {
      const products = await window.aivicApi.list(2);
      currentProducts = products?.filter(p => p.有効フラグ && p.AI予測対象フラグ) || [];
      renderProducts(currentProducts);
      renderPredictionResults(currentStoreId);
    } else {
      currentProducts = [];
      renderProducts([]);
      renderPredictionResults('');
    }
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    if (!validateDateRange()) return;
    filterProducts();
  });

  // リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#category-select').value = '';
    container.querySelector('#product-search').value = '';
    container.querySelector('#date-start').value = '';
    container.querySelector('#date-end').value = '';
    renderProducts(currentProducts);
  });

  // 商品検索（リアルタイム）
  container.querySelector('#product-search').addEventListener('input', filterProducts);
  container.querySelector('#category-select').addEventListener('change', filterProducts);

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括発注
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    if (confirm(`${checkedBoxes.length}件の商品を一括発注しますか？`)) {
      checkedBoxes.forEach(async (cb) => {
        const productId = cb.dataset.id;
        const quantityInput = container.querySelector(`.quantity-input[data-id="${productId}"]`);
        const reasonInput = container.querySelector(`.reason-input[data-id="${productId}"]`);

        if (quantityInput.value > 0) {
          // 簡易発注処理（モーダルなし）
          const orderData = {
            店舗ID: currentStoreId,
            商品ID: productId,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
            発注数量: parseInt(quantityInput.value),
            発注単価: 100,
            発注金額: parseInt(quantityInput.value) * 100,
            発注方法: '一括発注',
            発注ステータス: '発注済',
            仕入先ID: 'sup1',
            発注理由: reasonInput.value || '一括発注処理',
            自動発注フラグ: false,
            作成者ID: 'current-user',
            更新者ID: 'current-user'
          };

          await window.aivicApi.save(9, orderData);
        }
      });

      alert('一括発注が完了しました');
      container.querySelector('#select-all').checked = false;
      checkedBoxes.forEach(cb => cb.checked = false);
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 数量調整ボタン
    if (e.target.classList.contains('minus-btn')) {
      const input = container.querySelector(`.quantity-input[data-id="${e.target.dataset.id}"]`);
      const currentValue = parseInt(input.value) || 0;
      input.value = Math.max(0, currentValue - 1);
    }

    if (e.target.classList.contains('plus-btn')) {
      const input = container.querySelector(`.quantity-input[data-id="${e.target.dataset.id}"]`);
      const currentValue = parseInt(input.value) || 0;
      input.value = currentValue + 1;
    }

    // 発注ボタン
    if (e.target.classList.contains('order-btn')) {
      const productId = e.target.dataset.id;
      const product = currentProducts.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`.quantity-input[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`.reason-input[data-id="${productId}"]`);

      if (!product) return;

      const quantity = parseInt(quantityInput.value);
      if (quantity <= 0) {
        alert('発注量は正の数値を入力してください');
        return;
      }

      // モーダル表示
      selectedProductId = productId;
      container.querySelector('#modal-product-name').textContent = product.商品名;
      container.querySelector('#modal-order-quantity').value = quantity;
      container.querySelector('#modal-order-reason').value = reasonInput.value;

      // 納期予定日を7日後に設定
      const deliveryDate = new Date();
      deliveryDate.setDate(deliveryDate.getDate() + 7);
      container.querySelector('#modal-delivery-date').value = deliveryDate.toISOString().split('T')[0];

      container.querySelector('#order-modal').classList.remove('hidden');
    }
  });

  // 数量入力バリデーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const value = e.target.value;
      if (value && (isNaN(value) || parseFloat(value) < 0)) {
        e.target.setCustomValidity('発注量は正の数値を入力してください');
      } else {
        e.target.setCustomValidity('');
      }
    }
  });

  // モーダル関連
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  container.querySelector('#btn-order-cancel').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  container.querySelector('#btn-order-execute').addEventListener('click', () => {
    const quantity = container.querySelector('#modal-order-quantity').value;
    const reason = container.querySelector('#modal-order-reason').value;

    if (!quantity || quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return;
    }

    executeOrder(selectedProductId, quantity, reason);
  });

  // モーダル外クリックで閉じる
  container.querySelector('#order-modal').addEventListener('click', (e) => {
    if (e.target.id === 'order-modal') {
      container.querySelector('#order-modal').classList.add('hidden');
    }
  });
}
